                )}
                {children}
              </div>
            </div>
            {showArrow && <TooltipArrow className={arrowClassName} />}
          </div>
        </div>
      </TooltipContentContext.Provider>,
      portalTarget,
    );
  }

  // Classic and Staggered variants
  const entranceClass = isArrowEmerge
    ? ""
    : isStaggered
      ? ENTER_STAGGERED[side]
      : cn("zoom-in-95 duration-150", ENTER_FROM_SIDE[side]);

  return createPortal(
    <TooltipContentContext.Provider value={{ side, align }}>
      <div
        ref={contentRef}
        role="tooltip"
        className={cn(
          "absolute z-[9999] text-xs text-primary-foreground bg-primary shadow-md pointer-events-none box-border",
          (isArrowEmerge || isPop) && (ARROW_ORIGINS[side]?.[align] ?? "origin-center"),
          title
            ? "px-3.5 py-2.5 rounded-lg max-w-xs"
            : "px-3 py-1.5 rounded-md font-medium",
          !isArrowEmerge && !isPop && "transition-none",
          isArrowEmerge || isPop ? "" : entranceClass,
          className,
        )}
        style={
          {
            ...style,
            top: coords.top,
            left: coords.left,
            visibility: positioned ? "visible" : "hidden",
            ...(isPop
              ? {
                  animation: positioned
                    ? `tooltip-pop-${side} 320ms cubic-bezier(0.16, 1, 0.3, 1) both`
                    : undefined,
                  willChange: "transform, opacity",
                }
              : isArrowEmerge
                ? {
                    animation: positioned
                      ? `tooltip-emerge-${side} 600ms cubic-bezier(0.16, 1, 0.3, 1) both`
                      : undefined,
                    willChange: "transform, opacity",
                  }
                : undefined),
          } as React.CSSProperties
        }
        {...props}
      >
        {isPop && (
          <style>{`
            @keyframes tooltip-pop-top {
              0% {
                opacity: 0;
                transform: translateY(8px) scale(0.65);
              }
              60% {
                opacity: 1;
                transform: translateY(-2px) scale(1.04);
              }
              100% {
                opacity: 1;
                transform: translateY(0) scale(1);
              }
            }
            @keyframes tooltip-pop-bottom {
              0% {
                opacity: 0;
                transform: translateY(-8px) scale(0.65);
              }
              60% {
                opacity: 1;
                transform: translateY(2px) scale(1.04);
              }
              100% {
                opacity: 1;
